import{_ as i,o as e,c as o,e as r}from"./chunks/framework.YHAu34vx.js";const m=JSON.parse('{"title":"Proyecto: Laboratorio de Inteligencia Artificial con PHP","description":"","frontmatter":{},"headers":[],"relativePath":"04_php/100_proyecto_ia/prompt_cursor/1.md","filePath":"04_php/100_proyecto_ia/prompt_cursor/1.md"}'),l={name:"04_php/100_proyecto_ia/prompt_cursor/1.md"};function n(s,a,t,c,d,p){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="proyecto-laboratorio-de-inteligencia-artificial-con-php" tabindex="-1">Proyecto: Laboratorio de Inteligencia Artificial con PHP <a class="header-anchor" href="#proyecto-laboratorio-de-inteligencia-artificial-con-php" aria-label="Permalink to &quot;Proyecto: Laboratorio de Inteligencia Artificial con PHP&quot;">​</a></h1><p>Vamos a desarrollar una aplicación web educativa para que los alumnos aprendan a consumir APIs de inteligencia artificial utilizando PHP.</p><p>El objetivo es crear una aplicación atractiva y funcional que permita experimentar con diferentes capacidades de la IA, aplicando los conocimientos de programación adquiridos en clase.</p><h2 id="contexto" tabindex="-1">Contexto <a class="header-anchor" href="#contexto" aria-label="Permalink to &quot;Contexto&quot;">​</a></h2><p>Los alumnos conocen:</p><ul><li>Variables, constantes y tipos de datos.</li><li>Arrays indexados y asociativos.</li><li>Estructuras de control.</li><li>Funciones.</li><li>Formularios HTML con GET y POST.</li><li>Introducción a objetos y clases.</li><li>Sesiones PHP.</li><li>Procesamiento de JSON.</li></ul><p>El proyecto debe utilizar PHP sin frameworks y separar correctamente controladores, servicios y vistas.</p><p>La interfaz utilizará Tailwind CSS y DaisyUI, priorizando componentes sencillos y evitando largas listas de clases CSS.</p><h2 id="instrucciones-iniciales" tabindex="-1">Instrucciones iniciales <a class="header-anchor" href="#instrucciones-iniciales" aria-label="Permalink to &quot;Instrucciones iniciales&quot;">​</a></h2><ol><li>Lee y respeta las reglas definidas en <code>.cursor/rules/</code>.</li><li>Analiza el objetivo del proyecto.</li><li>Propón una arquitectura sencilla y didáctica.</li><li>Define una estructura de carpetas y archivos, indicando la responsabilidad de cada uno.</li><li>Identifica las fases de desarrollo recomendadas.</li><li>Indica los conocimientos PHP que se practicarán en cada fase.</li><li>Propón cómo integrar una API de IA mediante cURL y JSON.</li><li>Identifica qué configuración será necesaria para gestionar las claves API de forma segura.</li></ol><h2 id="restricciones" tabindex="-1">Restricciones <a class="header-anchor" href="#restricciones" aria-label="Permalink to &quot;Restricciones&quot;">​</a></h2><ul><li>No utilizar Laravel ni otros frameworks PHP.</li><li>No introducir patrones arquitectónicos complejos.</li><li>No utilizar bases de datos inicialmente.</li><li>No instalar dependencias innecesarias.</li><li>No generar todavía código de implementación.</li><li>No crear archivos ni carpetas.</li><li>No modificar las reglas existentes.</li></ul><h2 id="resultado-esperado" tabindex="-1">Resultado esperado <a class="header-anchor" href="#resultado-esperado" aria-label="Permalink to &quot;Resultado esperado&quot;">​</a></h2><p>Presenta una propuesta organizada que incluya:</p><ol><li>Resumen funcional de la aplicación.</li><li>Arquitectura propuesta.</li><li>Árbol de directorios.</li><li>Responsabilidad de los principales archivos.</li><li>Fases de implementación.</li><li>Posibles dificultades técnicas y didácticas.</li></ol><p><strong>IMPORTANTE: estamos en fase de planificación. No implementes nada hasta recibir mi autorización.</strong></p><p>Antes de finalizar, indica qué decisiones debemos tomar para comenzar la implementación.</p>',17)])])}const f=i(l,[["render",n]]);export{m as __pageData,f as default};
